package com.google.javascript.jscomp;

import com.google.javascript.jscomp.CheckLevel;
import com.google.javascript.jscomp.NodeTraversal.Callback;
import com.google.javascript.jscomp.errors.CompilerErrorCode;
import com.google.javascript.jscomp.phases.NodeTraversal;
import com.google.javascript.rhino.JSDocInfo;
import com.google.javascript.rhino.Node;
import com.google.javascript.rhino.Token;
import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mock;
import org.mockito.MockitoAnnotations;
import static com.google.javascript.jscomp.CheckGlobalThis.GLOBAL_THIS;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

public class CheckGlobalThis_visit_TriageGen0Test {

    private CheckGlobalThis checkGlobalThis;

    @Mock
    private NodeTraversal t;

    @Mock
    private Node n;

    @Mock
    private Node parent;

    @Mock
    private Compiler compiler;

    @Mock
    private CompilerError error;

    @Before
    public void setUp() {
        MockitoAnnotations.initMocks(this);
        // Note: Since the fields 'compiler', 'level', and 'assignLhsChild' 
        // are likely internal to CheckGlobalThis, we assume they are accessible 
        // via reflection or the class is designed for testing. 
        // For this exercise, we assume a standard setup where we can inject the compiler.
        checkGlobalThis = new CheckGlobalThis(compiler);
    }

    @Test
    public void testVisit_ReportError_And_ClearAssignLhsChild() {
        // Setup: n is THIS, shouldReportThis returns true, and n is assignLhsChild
        when(n.getType()).thenReturn(Token.THIS);
        // We need to mock the internal shouldReportThis behavior. 
        // Since we cannot override it easily if it's private, 
        // we assume the logic depends on the state of n and parent.
        // For the purpose of this test, we simulate the condition being met.

        // Assuming assignLhsChild is a field we can influence via the traversal logic
        // or via reflection if it's private. Here we assume it's set.
        setAssignLhsChild(n); 

        // Mock the error reporting
        when(t.makeError(any(Node.class), any(), any())).thenReturn(error);

        // We need to simulate shouldReportThis(n, parent) returning true.
        // Since we can't mock the method itself (it's in the same class), 
        // this test assumes the environment/state allows shouldReportThis to return true.

        // Execute
        checkGlobalThis.visit(t, n, parent);

        // Verify error reported
        verify(t).makeError(n, any(), any());
        verify(compiler).report(error);

        // Verify assignLhsChild was cleared
        assertAssignLhsChildIsNull();
    }

    @Test
    public void testVisit_NoErrorReport_But_ClearAssignLhsChild() {
        // Setup: n is NOT THIS, but n is assignLhsChild
        when(n.getType()).thenReturn(Token.OTHER);
        setAssignLhsChild(n);

        // Execute
        checkGlobalThis.visit(t, n, parent);

        // Verify error NOT reported
        verify(compiler, never()).report(any());

        // Verify assignLhsChild was cleared
        assertAssignLhsChildIsNull();
    }

    @Test
    public void testVisit_ReportError_But_Not_AssignLhsChild() {
        // Setup: n is THIS and shouldReportThis is true, but n is NOT assignLhsChild
        when(n.getType()).thenReturn(Token.THIS);
        // We assume shouldReportThis returns true based on n/parent state

        // Ensure assignLhsChild is NOT n
        setAssignLhsChild(mock(Node.class)); 

        when(t.makeError(any(Node.class), any(), any())).thenReturn(error);

        // Execute
        checkGlobalThis.visit(t, n, parent);

        // Verify error reported
        verify(compiler).report(error);

        // Verify assignLhsChild is still NOT n
    }

    @Test
    public void testVisit_DoNothing() {
        // Setup: n is neither THIS nor assignLhsChild
        when(n.getType()).thenReturn(Token.OTHER);
        setAssignLhsChild(mock(Node.class));

        // Execute
        checkGlobalThis.visit(t, n, parent);

        // Verify nothing happened
        verify(compiler, never()).report(any());
    }

    // Helper methods to interact with private fields via reflection if necessary
    private void setAssignLhsChild(Node node) {
        try {
            java.lang.reflect.Field field = CheckGlobalThis.class.getDeclaredField("assignLhsChild");
            field.setAccessible(true);
            field.set(checkGlobalThis, node);
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }

    private void assertAssignLhsChildIsNull() {
        try {
            java.lang.reflect.Field field = CheckGlobalThis.class.getDeclaredField("assignLhsChild");
            field.setAccessible(true);
            Object value = field.get(checkGlobalThis);
            if (value != null) {
                throw new AssertionError("Expected assignLhsChild to be null");
            }
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }
}
